import { isIP } from "node:net";
import { assertHostname } from "#/server/services/templates/naming.ts";
import { AppError, internalError } from "#/utils/error.ts";

/**
 * Free wildcard-DNS providers that map a hostname to an IP without any DNS
 * setup. Add a provider = add an entry to `freeDomainProviders`.
 */
export interface FreeDomainProvider {
	id: string;
	/** Hostname for `label` resolving to `ip`. */
	hostFor(label: string, ip: string): string;
	/** True when `host` was generated by this provider. */
	owns(host: string): boolean;
}

function ipLabel(ip: string): string {
	if (isIP(ip) === 4) return ip.replace(/\./g, "-");
	if (isIP(ip) === 6) return ip.replace(/:/g, "-");
	throw new AppError("FREE_DOMAIN_IP_INVALID", { ip });
}

/**
 * Wildcard-DNS services (`<label>.<ip-with-dashes>.<domain>` resolves to
 * the IP). Keyed by the FREE_DOMAIN_PROVIDER id.
 */
const FREE_DOMAIN_SERVICES: Record<string, { domain: string; ipv6: boolean }> =
	{
		"sslip.io": { domain: "sslip.io", ipv6: true },
		"nip.io": { domain: "nip.io", ipv6: false },
	};

function wildcardProvider(
	id: string,
	service: { domain: string; ipv6: boolean },
): FreeDomainProvider {
	return {
		id,
		hostFor: (label, ip) => {
			if (!service.ipv6 && isIP(ip) !== 4) {
				throw new AppError("FREE_DOMAIN_IPV4_ONLY", { provider: id });
			}
			return assertHostname(`${label}.${ipLabel(ip)}.${service.domain}`);
		},
		owns: (host) => host.endsWith(`.${service.domain}`),
	};
}

const freeDomainProviders: Record<string, FreeDomainProvider> =
	Object.fromEntries(
		Object.entries(FREE_DOMAIN_SERVICES).map(([id, service]) => [
			id,
			wildcardProvider(id, service),
		]),
	);

export function getFreeDomainProvider(id: string): FreeDomainProvider {
	const provider = freeDomainProviders[id];
	if (!provider) throw internalError(`Unknown free domain provider "${id}"`);
	return provider;
}
